insert into public.world_locations(slug,parent_id,location_type,name_th,name_en,description_th,map_x,map_y,scene_asset,danger_level,fast_travel)
select'astravor-gate',id,'dungeon','ประตูรากโลก','Worldroot Gate','ลานศิลาหน้าห้องแอสตราวอร์ จุดรวมวิญญาณผู้พ่ายแพ้',48,46,'/assets/nightcrown.png',7,false from public.world_locations where slug='aurelion'on conflict(slug)do nothing;
create table public.world_boss_life_states(boss_id uuid not null references public.world_bosses(id)on delete cascade,character_id uuid not null references public.characters(id)on delete cascade,user_id uuid not null references auth.users(id)on delete cascade,table_id uuid not null references public.dice_tables(id)on delete cascade,status text not null check(status in('dead','alive')),death_count integer not null default 0,respawn_count integer not null default 0,lost_items jsonb not null default'[]',last_died_at timestamptz,last_respawned_at timestamptz,updated_at timestamptz not null default now(),primary key(boss_id,character_id));
create table public.world_boss_life_events(id uuid primary key default gen_random_uuid(),boss_id uuid not null references public.world_bosses(id)on delete cascade,character_id uuid not null references public.characters(id)on delete cascade,user_id uuid not null references auth.users(id)on delete cascade,table_id uuid not null references public.dice_tables(id)on delete cascade,event_type text not null check(event_type in('death','respawn')),location_id bigint not null references public.world_locations(id),hp_after integer not null,lost_items jsonb not null default'[]',created_at timestamptz not null default now());
alter table public.world_boss_life_states enable row level security;alter table public.world_boss_life_events enable row level security;
create policy "Owners and raid members can view boss life state"on public.world_boss_life_states for select to authenticated using(user_id=auth.uid()or public.is_dice_table_member(table_id));create policy "Owners and raid members can view boss life events"on public.world_boss_life_events for select to authenticated using(user_id=auth.uid()or public.is_dice_table_member(table_id));
create or replace function public.record_world_boss_death(target_boss_id uuid,target_table_id uuid,target_character_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare v_hero public.characters%rowtype;v_state public.world_boss_life_states%rowtype;v_gate public.world_locations%rowtype;v_lost jsonb;begin if not exists(select 1 from public.dice_table_members where table_id=target_table_id and user_id=auth.uid()and role='dm')then raise exception'dm required';end if;if not exists(select 1 from public.dice_table_members where table_id=target_table_id and character_id=target_character_id and role in('player','dm'))then raise exception'combatant not found';end if;if not exists(select 1 from public.world_bosses where id=target_boss_id and status='active')then raise exception'boss inactive';end if;select*into v_hero from public.characters where id=target_character_id for update;if v_hero.id is null then raise exception'character not found';end if;select*into v_state from public.world_boss_life_states where boss_id=target_boss_id and character_id=v_hero.id for update;if v_state.status='dead'then raise exception'already dead';end if;select coalesce(jsonb_agg(jsonb_build_object('item_id',item.id,'slug',item.slug,'name_th',item.name_th,'quantity',stack.quantity)),'[]')into v_lost from public.character_item_stacks stack join public.content_items item on item.id=stack.content_item_id where stack.character_id=v_hero.id and item.rarity<>'soulbound';delete from public.character_item_stacks stack using public.content_items item where stack.content_item_id=item.id and stack.character_id=v_hero.id and item.rarity<>'soulbound';select*into v_gate from public.world_locations where slug='astravor-gate';update public.characters set hp_current=0,updated_at=now()where id=v_hero.id;insert into public.character_world_positions(character_id,user_id,location_id,arrived_at,updated_at)values(v_hero.id,v_hero.user_id,v_gate.id,now(),now())on conflict(character_id)do update set location_id=excluded.location_id,arrived_at=now(),updated_at=now();insert into public.world_boss_life_states(boss_id,character_id,user_id,table_id,status,death_count,lost_items,last_died_at)values(target_boss_id,v_hero.id,v_hero.user_id,target_table_id,'dead',1,v_lost,now())on conflict(boss_id,character_id)do update set table_id=excluded.table_id,status='dead',death_count=public.world_boss_life_states.death_count+1,lost_items=excluded.lost_items,last_died_at=now(),updated_at=now()returning*into v_state;insert into public.world_boss_life_events(boss_id,character_id,user_id,table_id,event_type,location_id,hp_after,lost_items)values(target_boss_id,v_hero.id,v_hero.user_id,target_table_id,'death',v_gate.id,0,v_lost);return jsonb_build_object('state',to_jsonb(v_state),'location',v_gate.name_th,'hp_current',0);end;$$;
create or replace function public.respawn_world_boss_character(target_boss_id uuid,target_character_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare v_hero public.characters%rowtype;v_state public.world_boss_life_states%rowtype;v_gate public.world_locations%rowtype;v_hp integer;begin select*into v_hero from public.characters where id=target_character_id and user_id=auth.uid()for update;if v_hero.id is null then raise exception'character not found';end if;select*into v_state from public.world_boss_life_states where boss_id=target_boss_id and character_id=v_hero.id for update;if v_state.character_id is null or v_state.status<>'dead'then raise exception'not dead';end if;select*into v_gate from public.world_locations where slug='astravor-gate';v_hp:=greatest(1,(v_hero.hp_max+1)/2);update public.characters set hp_current=v_hp,updated_at=now()where id=v_hero.id;update public.character_world_positions set location_id=v_gate.id,arrived_at=now(),updated_at=now()where character_id=v_hero.id;update public.world_boss_life_states set status='alive',respawn_count=respawn_count+1,last_respawned_at=now(),updated_at=now()where boss_id=target_boss_id and character_id=v_hero.id returning*into v_state;insert into public.world_boss_life_events(boss_id,character_id,user_id,table_id,event_type,location_id,hp_after)values(target_boss_id,v_hero.id,v_hero.user_id,v_state.table_id,'respawn',v_gate.id,v_hp);return jsonb_build_object('state',to_jsonb(v_state),'location',v_gate.name_th,'hp_current',v_hp,'hp_max',v_hero.hp_max,'items_restored',false);end;$$;
revoke all on function public.record_world_boss_death(uuid,uuid,uuid)from public;revoke all on function public.respawn_world_boss_character(uuid,uuid)from public;grant execute on function public.record_world_boss_death(uuid,uuid,uuid)to authenticated;grant execute on function public.respawn_world_boss_character(uuid,uuid)to authenticated;
alter publication supabase_realtime add table public.world_boss_life_states;alter publication supabase_realtime add table public.world_boss_life_events;
